<!doctype html><html><head><meta charset="utf-8"><style>
@page{margin:34px 34px 52px}body{font-family:'DejaVu Sans',sans-serif;font-size:9px;color:#26354d}h1{font-size:24px;margin:0;color:#152643}h2{font-size:13px;margin:22px 0 8px;color:#343a8a}.header{border-bottom:3px solid #6863db;padding-bottom:16px;margin-bottom:16px}table{width:100%;border-collapse:collapse}th,td{padding:7px 6px;text-align:left;vertical-align:top}th{background:#1d2c48;color:white;font-size:8px}td{border-bottom:1px solid #e2e7ef}thead{display:table-header-group}tr{page-break-inside:avoid}.right{text-align:right}.muted{color:#63748d}.meta td{border:0;padding:4px}.total{background:#edf0ff;font-weight:bold}.note{white-space:pre-wrap;overflow-wrap:break-word;background:#f2f4fa;padding:12px}.footer{position:fixed;bottom:-30px;color:#64748b;font-size:8px}.small{font-size:8px}.section{page-break-before:always}
